// Groups draft pre-bills by the matter's responsible attorney -- each attorney gets one review
// email listing everything they need to review this cycle, rather than one email per bill.
const bills = $input.first().json.data || [];
const groups = {};

for (const bill of bills) {
  const attorney = (bill.matter && bill.matter.responsible_attorney) || {};
  const key = attorney.email || 'unassigned';
  if (!groups[key]) {
    groups[key] = { attorney_name: attorney.name || 'Unassigned', attorney_email: attorney.email || '', bills: [] };
  }
  groups[key].bills.push({
    bill_id: bill.id,
    bill_number: bill.number || '',
    total: Number(bill.total || 0),
    matter_ref: (bill.matter && bill.matter.display_number) || '',
    matter_description: (bill.matter && bill.matter.description) || '',
    client_name: (bill.client && bill.client.name) || '',
  });
}

const unassigned_count = (groups['unassigned'] || { bills: [] }).bills.length;
const attorney_groups = Object.entries(groups)
  .filter(([key]) => key !== 'unassigned')
  .map(([, g]) => g);

return [{ json: {
  attorney_groups,
  has_draft_prebills: attorney_groups.length > 0,
  unassigned_count,
} }];

const FIRM_NAME = $vars.FIRM_NAME;
const FIRM_FROM_EMAIL = $vars.FIRM_FROM_EMAIL;
const BILLING_URL = $vars.FIRM_CLIO_BILLING_URL || 'https://app.clio.com/bills?status=draft';
const DEADLINE_DAY = $vars.FIRM_BILLING_DEADLINE_DAY || '28';

if (!FIRM_NAME) throw new Error('FIRM_NAME n8n Variable is not set. Go to Settings → Variables and add it.');
if (!FIRM_FROM_EMAIL) throw new Error('FIRM_FROM_EMAIL n8n Variable is not set. Go to Settings → Variables and add it.');

function ordinal(n) {
  n = Number(n);
  const s = ['th', 'st', 'nd', 'rd'];
  const v = n % 100;
  return n + (s[(v - 20) % 10] || s[v] || s[0]);
}

const item = $input.first().json;
const bills = item.bills;
const total = bills.reduce((s, b) => s + b.total, 0);
const lines = bills.map(b => `  • ${b.matter_ref} — ${b.client_name} — $${b.total.toFixed(2)}${b.matter_description ? ' (' + b.matter_description + ')' : ''}`);

const subject = `${bills.length} pre-bill(s) ready for your review — billing closes on the ${ordinal(DEADLINE_DAY)}`;
const body = `Hi ${item.attorney_name},

You have ${bills.length} draft pre-bill(s) ready for your review this cycle (total $${total.toFixed(2)}):

${lines.join('\n')}

Review, edit, and finalize each one directly in Clio:
${BILLING_URL}

Please finish your review by the ${ordinal(DEADLINE_DAY)} so bills can go out to clients on time.

— ${FIRM_NAME} Billing System`;

return [{ json: {
  ...item,
  channel: 'email',
  recipient: item.attorney_email,
  from_email: FIRM_FROM_EMAIL,
  subject,
  message: body,
  template_id: 'PAC-61',
  matter_id: '',
} }];

// The firm has ONE shared billing deadline each month (not a per-bill due date like
// invoices), so the nudge tier is computed once per run and applied to every outstanding
// pre-bill alike.
const DEADLINE_DAY = Number($vars.FIRM_BILLING_DEADLINE_DAY) || 28;

// Formats a Date using its LOCAL year/month/day -- not .toISOString(), which converts to UTC
// and silently shifts the date by one whenever the n8n server's timezone isn't UTC exactly (e.g.
// UTC+1 turns local midnight into 11pm the previous day in UTC). Confirmed live: without this,
// deadline_date came back one day early in a UTC+1 environment.
function toLocalYMD(d) {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${dd}`;
}

const today = new Date();
today.setHours(0, 0, 0, 0);
// JS Date auto-rolls a day number past the end of the month into the next month (e.g. day 31
// in a 30-day month becomes the 1st of next month) -- pick a deadline day of 28 or lower to avoid this.
const deadline = new Date(today.getFullYear(), today.getMonth(), DEADLINE_DAY);
deadline.setHours(0, 0, 0, 0);

const msPerDay = 24 * 60 * 60 * 1000;
const daysUntilDeadline = Math.round((deadline - today) / msPerDay);

// Specific offsets only, not a continuous range -- avoids nudging every single day. Mirrors the
// discrete-window ladder the Invoice Reminder Ladder (PAC-18) uses, just anchored to one shared
// firm deadline instead of a per-invoice due date.
let tier = 'none';
if      (daysUntilDeadline === 3)  tier = 'reminder';
else if (daysUntilDeadline === 1)  tier = 'urgent';
else if (daysUntilDeadline === 0)  tier = 'overdue';
else if (daysUntilDeadline === -3) tier = 'overdue';
else if (daysUntilDeadline === -7) tier = 'overdue';

return [{ json: {
  tier,
  is_nudge_day: tier !== 'none',
  days_until_deadline: daysUntilDeadline,
  deadline_date: toLocalYMD(deadline),
} }];

// Same grouping logic as 'Group Pre-Bills By Attorney' in the compile half of this workflow,
// plus the nudge tier carried forward explicitly since the Clio API call above replaced the
// item's json.
const tierInfo = $('Compute Nudge Tier For Today').item.json;
const bills = $input.first().json.data || [];
const groups = {};

for (const bill of bills) {
  const attorney = (bill.matter && bill.matter.responsible_attorney) || {};
  const key = attorney.email || 'unassigned';
  if (!groups[key]) {
    groups[key] = { attorney_name: attorney.name || 'Unassigned', attorney_email: attorney.email || '', bills: [] };
  }
  groups[key].bills.push({
    bill_id: bill.id,
    bill_number: bill.number || '',
    total: Number(bill.total || 0),
    matter_ref: (bill.matter && bill.matter.display_number) || '',
    matter_description: (bill.matter && bill.matter.description) || '',
    client_name: (bill.client && bill.client.name) || '',
  });
}

const attorney_groups = Object.entries(groups)
  .filter(([key]) => key !== 'unassigned')
  .map(([, g]) => g);

return [{ json: {
  attorney_groups,
  has_draft_prebills: attorney_groups.length > 0,
  tier: tierInfo.tier,
  days_until_deadline: tierInfo.days_until_deadline,
} }];

