const PARTNER_EMAIL = $vars.FIRM_PARTNER_EMAIL;
const FIRM_FROM_EMAIL = $vars.FIRM_FROM_EMAIL;
const BILLING_URL = $vars.FIRM_CLIO_BILLING_URL || 'https://app.clio.com/bills?status=draft';

if (!PARTNER_EMAIL) throw new Error('FIRM_PARTNER_EMAIL n8n Variable is not set. Go to Settings → Variables and add it.');
if (!FIRM_FROM_EMAIL) throw new Error('FIRM_FROM_EMAIL n8n Variable is not set. Go to Settings → Variables and add it.');

const item = $input.first().json;
const bills = item.bills;
const total = bills.reduce((s, b) => s + b.total, 0);
const lines = bills.map(b => `  • ${b.matter_ref} — ${b.client_name} — $${b.total.toFixed(2)}`);
const overdueDays = item.days_until_deadline < 0 ? Math.abs(item.days_until_deadline) : 0;

const subject = `Billing deadline${overdueDays > 0 ? ' passed' : ' reached'}: ${item.attorney_name} has ${bills.length} unreviewed pre-bill(s)`;
const body = `${item.attorney_name} (${item.attorney_email}) still has ${bills.length} draft pre-bill(s) unreviewed${overdueDays > 0 ? ', ' + overdueDays + ' day(s) past' : ' as of'} this month's billing deadline (${item.deadline_date || ''}).

Outstanding pre-bills (total $${total.toFixed(2)}):
${lines.join('\n')}

Review directly in Clio:
${BILLING_URL}

— ${FIRM_NAME} Billing System`;

return [{ json: {
  ...item,
  channel: 'email',
  recipient: PARTNER_EMAIL,
  from_email: FIRM_FROM_EMAIL,
  subject,
  message: body,
  template_id: 'PAC-61',
