const FIRM_FROM_EMAIL = $vars.FIRM_FROM_EMAIL;
const BILLING_URL = $vars.FIRM_CLIO_BILLING_URL || 'https://app.clio.com/bills?status=draft';

if (!FIRM_FROM_EMAIL) throw new Error('FIRM_FROM_EMAIL n8n Variable is not set. Go to Settings → Variables and add it.');

const item = $input.first().json;
const bills = item.bills;
const total = bills.reduce((s, b) => s + b.total, 0);
const lines = bills.map(b => `  • ${b.matter_ref} — ${b.client_name} — $${b.total.toFixed(2)}`);

const TIER_COPY = {
  reminder: { label: 'Reminder', tone: `Billing closes in ${item.days_until_deadline} day(s).` },
  urgent:   { label: 'Urgent',   tone: 'Billing closes tomorrow.' },
};
const copy = TIER_COPY[item.tier] || TIER_COPY.reminder;

const subject = `${copy.label}: ${bills.length} pre-bill(s) still need your review`;
const body = `Hi ${item.attorney_name},

${copy.tone} You still have ${bills.length} draft pre-bill(s) waiting for your review (total $${total.toFixed(2)}):

${lines.join('\n')}

Review and finalize in Clio:
${BILLING_URL}

— ${FIRM_NAME} Billing System`;

return [{ json: {
  ...item,
  channel: 'email',
  recipient: item.attorney_email,
  from_email: FIRM_FROM_EMAIL,
  subject,
  message: body,
  template_id: 'PAC-61',
  matter_id: '',
